    "content": [
      {
        "type": "hero",
        "title": "About Us",
        "subtitle": "A center for prayer, learning, and community"
      },
      {
        "type": "text",
        "body": "Minhaajulhudaa Masjid was established in 2020 to serve the growing Muslim community in Lagos. Our masjid provides a spiritual home for daily prayers, Jumu'ah, Taraweeh during Ramadan, and a center for Islamic learning and community activities."
      },
      {
        "type": "text",
        "body": "With a capacity of 2,000 worshippers, our facility includes a main prayer hall, sisters' section, wudu areas, classrooms for Islamic education, a library, and administrative offices. We are committed to following the Qur'an and Sunnah in all our affairs."
      }
    ],
